public class Nodo {

    // Atributos del nodo. Privados por falta de herencia.

    private String codigoNodo;
    private float capacidad;
    private boolean gpu;
    private boolean disponibilidad;


    // Constructor default
    public Nodo() {
        codigoNodo = "";
        capacidad = 0;
        gpu = false;
        disponibilidad = true;
    }


    // Constructor lleno
    public Nodo(String codigoNodo, float capacidad, boolean gpu) {
        this.codigoNodo = codigoNodo;
        this.capacidad = capacidad;
        this.gpu = gpu;
        disponibilidad = true;
    }


    // Setters y getters de los atributos

    public void setCodigoNodo(String newCodigo) {
        codigoNodo = newCodigo;
    }

    public String getCodigoNodo() {
        return codigoNodo;
    }


    public void setCapacidad(float newCapacidad) {
        capacidad = newCapacidad;
    }

    public float getCapacidad() {
        return capacidad;
    }


    public void setGpu(boolean newGpu) {
        gpu = newGpu;
    }

    public boolean getGpu() {
        return gpu;
    }


    public void setDisponibilidad(boolean newDisponibilidad) {
        disponibilidad = newDisponibilidad;
    }

    public boolean getDisponibilidad() {
        return disponibilidad;
    }


    // Override del toString de "papa Dios" (osea el Object)

    @Override
    public String toString() {
        String tieneGpu;
        String estaDisponible;
        // Determina si el nodo cuenta con GPU.
        if (gpu) {
            tieneGpu = "Sí";
        }
        else {
            tieneGpu = "No";
        }

        // Responde a si está libre o no
        if (disponibilidad) {
            estaDisponible = "Sí";
        }
        else {
            estaDisponible = "No";
        }

        //Muestra la info
        return "Código del nodo: " + codigoNodo
            + "\nCapacidad máxima: " + capacidad + " horas"
            + "\nTiene GPU: " + tieneGpu
            + "\nDisponible: " + estaDisponible;
    }
}
